def _cargar():
    return pickle.loads(zlib.decompress(base64.b64decode("".join(_BLOB.split()))))


class Guardian:
    def __init__(self):
        self._m = None

    def _modelos(self):
        if self._m is None:
            self._m = _cargar()
        return self._m

    def _prob(self, caso):
        m = self._modelos()
        x = np.nan_to_num(np.asarray(_extract_feats(caso), dtype=np.float64))
        z = float(((x - m["mu"]) / m["sd"]) @ m["coef"] + m["b"])
        p_lr = 1.0 / (1.0 + np.exp(-np.clip(z, -30.0, 30.0)))
        x32 = x.astype(np.float32)
        acc = 0.0
        for left, right, feat, thr, leaf in m["trees"]:
            n = 0
            while left[n] != -1:
                n = left[n] if x32[feat[n]] <= thr[n] else right[n]
            acc += leaf[n]
        p_et = acc / len(m["trees"])
        return _W_LR * p_lr + (1.0 - _W_LR) * p_et

    def score(self, caso):
        try:
            p = self._prob(caso)
        except Exception:
            return 0.6                      # ante un fallo, mejor revisar
        u = _U_FINAL
        s = 0.5 * p / u if p <= u else 0.5 + 0.5 * (p - u) / (1.0 - u)
        return float(min(1.0, max(0.0, s)))


Bot = Guardian
